# Kaggle eval runner: runs a submission bundle on the public training tasks with the official harness.
# Generated by scripts/make_eval_kernel.py -- placeholders below are filled in at generation time.
import asyncio
import base64
import glob
import json
import logging
import os
import re
import shutil
import subprocess
import sys
import time
from pathlib import Path

BUNDLE_FILES = json.loads(base64.b64decode("").decode())
RUN = json.loads(base64.b64decode("eyJ0YXNrX2lkcyI6IG51bGwsICJjb25jdXJyZW5jeSI6IDQsICJidW5kbGUiOiAidjAzX2xvY2F0ZSIsICJ0YWciOiAiZnVsbCJ9").decode())
T0 = time.time()


def log(msg):
    print(f"[{(time.time() - T0) / 60:6.1f}m] {msg}", flush=True)


os.environ.update({
    'TRANSFORMERS_NO_TF': '1', 'TRANSFORMERS_NO_FLAX': '1', 'TRANSFORMERS_OFFLINE': '1',
    'VLLM_NO_USAGE_STATS': '1', 'VLLM_WORKER_MULTIPROC_METHOD': 'spawn',
    'VLLM_ENGINE_READY_TIMEOUT_S': '1200', 'VLLM_MEMORY_PROFILER_ESTIMATE_CUDAGRAPHS': '1',
    'NCCL_DEBUG': 'WARN', 'LITELLM_LOCAL_MODEL_COST_MAP': 'True', 'LITELLM_TELEMETRY': 'False',
    'LITELLM_LOG': 'WARNING', 'OPENAI_API_KEY': 'EMPTY', 'LOCAL_API_KEY': 'EMPTY',
    'PYTORCH_CUDA_ALLOC_CONF': 'expandable_segments:True', 'OTEL_SDK_DISABLED': 'true',
    'OTEL_PYTHON_DISABLED': 'true',
})
for name in ('LiteLLM', 'LiteLLM Router', 'LiteLLM Proxy', 'litellm', 'httpx', 'httpcore', 'openai',
             'urllib3', 'opentelemetry', 'opentelemetry.context'):
    lg = logging.getLogger(name)
    lg.setLevel(logging.WARNING)
    if 'litellm' in name.lower():
        lg.propagate = False
        lg.handlers.clear()

# ---------------------------------------------------------------- install harness (same as starter)
log(f"nproc={os.cpu_count()}")
subprocess.run("nvidia-smi --query-gpu=name,memory.total --format=csv", shell=True)
WHEELHOUSE = Path(glob.glob('/kaggle/input/**/gemma-4-developer-agent-wheelhouse', recursive=True)[0])
for pth_pattern in ('/usr/local/lib/python*/dist-packages/*cutlass*.pth',
                    '/usr/local/lib/python*/site-packages/*cutlass*.pth'):
    for pth in glob.glob(pth_pattern):
        try:
            os.unlink(pth)
        except OSError:
            pass
tmp_whl = Path('/tmp/wheelhouse')
tmp_whl.mkdir(parents=True, exist_ok=True)
for w in WHEELHOUSE.glob('*.whl'):
    if 'cutlass' in w.name.lower():
        continue
    target = tmp_whl / (w.name.replace('cu128', '+cu128') if ('cu128' in w.name and '+' not in w.name) else w.name)
    if not target.exists():
        try:
            os.symlink(w, target)
        except OSError:
            shutil.copyfile(w, target)
subprocess.run([sys.executable, '-m', 'pip', 'install', '-q', '--no-deps', '--force-reinstall',
                *sorted(str(w) for w in tmp_whl.glob('*.whl'))], check=True)
log("wheels installed")

# ---------------------------------------------------------------- write bundle
DATA_DIR = Path(glob.glob('/kaggle/input/**/gemma-4-developer-agent/tasks.jsonl', recursive=True)[0]).parent
WORK = Path('/kaggle/working')
AGENT_DIR = WORK / 'bundle'
shutil.rmtree(AGENT_DIR, ignore_errors=True)
for rel, b64 in BUNDLE_FILES.items():
    p = AGENT_DIR / rel
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_bytes(base64.b64decode(b64))
log(f"bundle written: {sorted(BUNDLE_FILES)}  run={RUN}")

import litellm  # noqa: E402
import torch  # noqa: E402
import yaml  # noqa: E402
from adk_submission import VllmConfig, VllmServer, discover_adapters, validate_directory  # noqa: E402
from adk_submission.discovery import discover_declared_models  # noqa: E402
from google.adk.agents.context_cache_config import ContextCacheConfig  # noqa: E402
from google.adk.apps._configs import EventsCompactionConfig  # noqa: E402
from swegemma.config import ALLOWED_ADAPTER_EXTENSIONS, EvalConfig, build_submission_limits  # noqa: E402
from swegemma.evaluate import Evaluator  # noqa: E402
from swegemma.models import load_tasks  # noqa: E402

litellm.drop_params = True
limits, gen_constraints = build_submission_limits()
validate_directory(AGENT_DIR, limits=limits)
declared = discover_declared_models(AGENT_DIR)
assert len(declared) == 1, declared
model_name = next(iter(declared))
MODEL_PATH = Path(glob.glob(f'/kaggle/input/**/{model_name}/*/config.json', recursive=True)[0]).parent
log(f"model {model_name} at {MODEL_PATH}")

adapters = discover_adapters(str(AGENT_DIR), adapter_extensions=ALLOWED_ADAPTER_EXTENSIONS)
adapter_map = getattr(adapters, 'adapters', None) or {}
ranks = [r for info in adapter_map.values() if (r := getattr(info, 'rank', None))]
extra = {'gemma-4-12b-it-qat-w4a16-ct': ('--hf-overrides',
                                          '{"architectures": ["Gemma4ForCausalLM"], "model_type": "gemma4"}')}
server = VllmServer(VllmConfig(
    model=str(MODEL_PATH), port=8000, host='127.0.0.1', tool_call_parser='gemma4', reasoning_parser='gemma4',
    max_model_len=32768, dtype='bfloat16', gpu_memory_utilization=0.90, enable_auto_tool_choice=True,
    enable_lora=bool(adapter_map), max_loras=max(1, len(adapter_map)),
    max_lora_rank=max(ranks) if ranks else 128, scheduler_reserve_full_isl=False,
    tensor_parallel_size=min(4, torch.cuda.device_count()), startup_timeout=60 * 20,
    extra_args=extra.get(model_name, ()),
), adapter_manifest=adapters)
server.start()
models = server.create_model_registry(aliases=[model_name], model_prefix='openai/', api_key='EMPTY')
log("vLLM up")

# ---------------------------------------------------------------- run eval
ev_raw = {}
if (AGENT_DIR / 'eval_config.yaml').exists():
    ev_raw = yaml.safe_load((AGENT_DIR / 'eval_config.yaml').read_text()) or {}
ev = ev_raw.get('evaluation', ev_raw)
tasks = load_tasks(DATA_DIR / 'tasks.jsonl')
task_ids = RUN.get('task_ids') or [t.instance_id for t in tasks]
RESULTS = WORK / 'results'
cfg = EvalConfig(
    tasks_path=DATA_DIR / 'tasks.jsonl', snapshots_dir=DATA_DIR / 'snapshots', results_dir=RESULTS,
    submission_dir=AGENT_DIR, models=models, sandbox='subprocess',
    timeout_seconds=int(ev.get('timeout_seconds', 300)), verification_timeout_seconds=300,
    max_time_minutes=float(ev.get('max_time_minutes', 60.0)), max_tool_calls=int(ev.get('max_tool_calls', 100)),
    max_turns=int(ev['max_turns']) if ev.get('max_turns') is not None else None,
    limits=limits, generation_constraints=gen_constraints, adapter_manifest=adapters,
    context_cache_config=ContextCacheConfig(min_tokens=2048, ttl_seconds=1800, cache_intervals=10),
    events_compaction_config=EventsCompactionConfig(compaction_interval=15, overlap_size=2,
                                                    token_threshold=14336, event_retention_size=5),
    graph_dir=str(DATA_DIR / 'graphs'), embeddings_dir=str(DATA_DIR / 'embeddings'),
    wheels_dir=DATA_DIR / 'wheels', task_ids=task_ids, concurrency=int(RUN.get('concurrency', 4)),
    display_mode='quiet', verbose=False,
)
log(f"running {len(task_ids)} tasks, concurrency={cfg.concurrency}, eval={ev}")
res = asyncio.run(Evaluator(cfg).run())
n = len(res.task_results)
solved = sum(1 for r in res.task_results if r.resolved)
log(f"DONE resolved {solved}/{n} = {solved / max(n, 1):.3f}")
server.stop()
